 "content": "def transform(grid):
    """Collapse consecutive identical rows and columns in a stripe lattice."""
    rows = []
    for row in grid:
        row = list(row)
        if not rows or row != rows[-1]:
            rows.append(row)

    if not rows:
        return []

    out = []
    previous = None
    for col in range(len(rows[0])):
        column = tuple(row[col] for row in rows)
        if column != previous:
            for r, value in enumerate(column):
                if len(out) <= r:
                    out.append([])
                out[r].append(value)
            previous = column
    return out
